const input = document.getElementById('faqSearch');
const noRes = document.getElementById('noResults');
const qas = [...document.querySelectorAll('.qa')];
const groups = [...document.querySelectorAll('.faq-group')];
input.addEventListener('input', () => {
  const q = input.value.trim().toLowerCase();
  let shown = 0;
  qas.forEach(d => {
    const match = !q || d.textContent.toLowerCase().includes(q);
    d.classList.toggle('hide', !match);
    if (match) shown++;
    if (q && match) d.open = true;
  });
  groups.forEach(g => {
    const any = [...g.querySelectorAll('.qa')].some(d => !d.classList.contains('hide'));
    g.style.display = any ? '' : 'none';
  });
  noRes.classList.toggle('show', q && shown === 0);
});
